const rows={"world_ancient": [[-3000, "紀元前3000年ごろ", "古代エジプト文明を支えた川は、{ないる|ナイル}川", "毎年の増水が流域に肥沃な土を運び、農耕や人びとの暮らしを支えました。", "にじぇーる|いんだす|がんじす", "nile"], [-3200, "紀元前3200年ごろ", "古代エジプトで使われた象形文字は、{ひえろぐりふ|ヒエログリフ}", "動物や道具などの形を用いる文字で、神殿や墓の碑文などに使われました。", "あるふぁべっと|きっぷ|ぼんじ", "egypt"], [-3300, "紀元前3300年ごろ", "メソポタミアで生まれた、{くさびがた|楔形}文字", "葦の筆などを粘土板に押しつけて記しました。シュメール語をはじめ多くの言語の表記に使われました。", "しょうけい|こうこつ|あるふぁべっと", "writing"], [-1750, "紀元前18世紀", "法についての石碑を残したバビロニアの王は、{はんむらび|ハンムラビ}", "王の裁定を刻んだ石碑には、財産・家族・商業などに関する決まりが記されています。", "あうぐすとぅす|くふ|だれいおす", "hammurabi"], [-776, "紀元前776年（伝承上の初回）", "古代オリンピックが開かれた聖域は、{おりんぴあ|オリンピア}", "ゼウス神をたたえる競技祭で、古代ギリシャの各地から選手が集まりました。", "あてね|すぱるた|ころんとす", "greek"], [-334, "紀元前334年", "東方遠征を始めたマケドニア王、{あれくさんどろす|アレクサンドロス}", "ペルシャ帝国を倒し、東西の文化が交流するヘレニズム世界の形成につながりました。", "ぺりくれす|はんにばる|あうぐすとぅす", "alexander"], [-27, "紀元前27年", "ローマで初代皇帝とされる人物は、{あうぐすとぅす|アウグストゥス}", "元老院からこの尊称を受け、ローマの帝政の基礎を築きました。", "かえさる|ねろ|とらやぬす", "rome"], [-13, "紀元前13年", "アウグストゥスの時代に建設が決まった平和の祭壇は、{あらぱきす|アラ・パキス}", "紀元前9年に奉献された祭壇で、皇帝と平和を結びつけるローマの美術の例です。", "ころっせお|ぱるてのん|じっぐらと", "rome"], [-221, "紀元前221年", "中国を統一し、最初の皇帝を名乗った秦の、{しこうてい|始皇帝}", "戦国時代の諸国を征服し、文字・貨幣・度量衡などの統一を進めました。", "ぶてい|たいそう|こうぶてい", "qin"], [-210, "紀元前210年ごろ", "秦の始皇帝の陵墓を守るためにつくられた、{へいばよう|兵馬俑}", "兵士や馬をかたどった多数の像です。1974年に発見され、秦の巨大な陵墓の一部として知られます。", "どぐう|はにわ|もあい", "qin"]], "world_medieval": [[500, "中世の地中海世界", "ビザンツ帝国の都となった、{こんすたんてぃのーぷる|コンスタンティノープル}", "330年にローマ皇帝コンスタンティヌスが都とし、後の東ローマ帝国の中心となりました。", "ろーま|あてね|あれくさんどりあ", "byzantine"], [532, "532年", "ユスティニアヌス帝が再建を始めた大聖堂は、{はぎあそふぃあ|ハギア・ソフィア}", "コンスタンティノープルに建てられた大建築で、537年に完成しました。", "のーとるだむ|さんぴえとろ|さぐらだふぁみりあ", "byzantine"], [750, "750年", "ウマイヤ朝に代わって成立したイスラム王朝は、{あっばーす|アッバース}朝", "政治と文化の中心がイラク方面に移り、都市や学問・商業が発展しました。", "ふぁーてぃま|あいゆーぶ|おすまん", "abbasid"], [762, "762年", "アッバース朝の新しい都となった、{ばぐだーど|バグダード}", "円形の都市として建設され、イスラム世界の学問・交易の中心地として栄えました。", "だますくす|かいろ|こるどば", "abbasid"], [1215, "1215年", "イングランドのジョン王が認めた、{まぐなかるた|マグナ・カルタ}", "王の権力にも制限があるという考えを示した文書で、後の法や議会の歴史に影響しました。", "けんりしょうてん|どくりつせんげん|なんとのおうれい", "magna"], [1258, "1258年", "フレグの軍に攻略され、アッバース朝の都としての役割を失った、{ばぐだーど|バグダード}", "モンゴル勢力の征服により、西アジアの政治勢力の配置が大きく変化しました。", "かいろ|めっか|だますくす", "ilkhan"], [1271, "1271年", "中国で元を建てたモンゴルの君主は、{ふびらい|フビライ}", "チンギス・ハンの孫で、国号を元と定めました。元は1279年に南宋を滅ぼしました。", "おごたい|ちむーる|ばとぅ", "yuan"], [1271, "13世紀後半", "元の都・大都が置かれた、現在の都市は、{ぺきん|北京}", "元の皇帝は大都を拠点に支配を進めました。この都市は後の明・清でも都として重要でした。", "なんきん|しゃんはい|こうしゅう", "yuan"], [1455, "1455年ごろ", "ヨーロッパで金属活字を使った聖書の印刷を進めた、{ぐーてんべるく|グーテンベルク}", "東アジアには先行する活字印刷があります。彼の技術は西ヨーロッパで本の生産と知識の普及を変えました。", "るたー|がりれお|まぜらん", "print"], [1455, "1455年ごろ", "グーテンベルク聖書が印刷されたドイツの都市は、{まいんつ|マインツ}", "ヨーロッパの印刷文化を代表する初期の本です。印刷後に手作業で彩色された部分もあります。", "ろーま|りすぼん|ぱり", "print"]], "world_early_modern": [[1492, "1492年", "大西洋を渡ってカリブ海の島々に到達した、{ころんぶす|コロンブス}", "スペインの支援を受けて航海しました。アメリカ大陸にはそれ以前から多様な社会と文化がありました。", "ばすこだがま|まぜらん|くっく", "columbus"], [1503, "16世紀初め", "「モナ・リザ」を描いた、{れおなるどだびんち|レオナルド・ダ・ヴィンチ}", "ルネサンスの芸術家で、絵画だけでなく自然や技術の研究にも関心を持ちました。", "みけらんじぇろ|らふぁえろ|ぼってぃちぇり", "leonardo"], [1517, "1517年", "宗教改革のきっかけとなる問題提起をした、{るたー|ルター}", "贖宥状などをめぐって教会のあり方を問い、ヨーロッパの宗教と社会に大きな影響を与えました。", "かるばん|いぐなちうすろよら|えらすむす", "reform"], [1543, "1543年", "地球が太陽の周りを回る体系を著書で示した、{こぺるにくす|コペルニクス}", "「天球の回転について」を刊行しました。この考え方は、その後の天文学の発展につながりました。", "ぷとれまいおす|にゅーとん|べーこん", "copernicus"], [1644, "1644年", "北京に入り、中国本土の支配を広げた王朝は、{しん|清}", "満洲に起源を持つ王朝で、1911年の辛亥革命を経て、1912年に皇帝が退位しました。", "みん|げん|そう", "qing"], [1644, "17世紀以降", "清の支配者の出身となった民族は、{まんしゅう|満洲}人", "清は多くの民族や地域を統治した帝国で、中国と周辺地域の歴史に影響を与えました。", "もんごる|とるこ|すらぶ", "qing"], [1682, "1682年", "宮廷と政治の中心をベルサイユに置いたフランス王は、{るいじゅうよんせい|ルイ14世}", "豪華な宮殿と宮廷儀礼を通じ、王権の強さを示しました。絶対王政を学ぶ代表例です。", "るいじゅうろくせい|あんりよんせい|ふらんそわいっせい", "versailles"], [1688, "1688年", "イングランドで王が交代する、{めいよかくめい|名誉革命}", "ジェームズ2世が退き、翌年ウィリアム3世とメアリ2世が即位しました。議会の役割が強まりました。", "せいきょうとかくめい|ふらんすかくめい|さんがつかくめい", "glorious"], [1776, "1776年", "北米の13植民地が採択した、{どくりつせんげん|独立宣言}", "7月4日に宣言の文面が採択され、イギリスからの独立を世界に示しました。全員が同日に署名したわけではありません。", "じんけんせんげん|けんりしょうてん|まぐなかるた", "independence"], [1776, "1776年", "北米の13植民地が独立を宣言した相手の国は、{いぎりす|イギリス}", "本国の課税政策などへの反発を背景に独立戦争が起こり、アメリカ合衆国の成立へつながりました。", "ふらんす|すぺいん|おらんだ", "independence"]], "world_modern": [[1789, "1789年", "フランス革命の中で採択された、{じんけんせんげん|人権宣言}", "人は自由で権利において平等に生まれるという理念などを示し、後の政治に大きな影響を与えました。", "けんりしょうてん|どくりつせんげん|まぐなかるた", "rights"], [1804, "1804年", "フランスの民法典の整備を進めた、{なぽれおん|ナポレオン}", "財産や契約、家族などの民事関係を体系化しました。多くの国の法制度にも影響しました。", "るいじゅうよんせい|びすまるく|めってるにひ", "civil"], [1760, "18世紀後半から", "産業革命が最初に本格化した国は、{いぎりす|イギリス}", "繊維工業などで機械化と工場生産が進み、仕事や暮らし、都市の姿を大きく変えました。", "ふらんす|どいつ|ろしあ", "industrial"], [1769, "1769年", "蒸気機関の改良で知られる、{わっと|ワット}", "蒸気機関を初めて発明した人物ではありません。効率を高める改良が工場などへの普及に役立ちました。", "えじそん|ふぁらでー|ぐーてんべるく", "industrial"], [1815, "1815年", "ナポレオン戦争後のヨーロッパ秩序を話し合った、{うぃーん|ウィーン}会議", "1814年から1815年に開かれ、革命や戦争で変わった国境や勢力関係を調整しました。", "ぱり|ろんどん|べるりん", "vienna"], [1914, "1914年", "サラエボ事件などをきっかけに始まった、{だいいちじせかいたいせん|第一次世界大戦}", "同盟関係や帝国主義的な対立が重なり、ヨーロッパから世界各地を巻き込む戦争になりました。", "だいにじせかいたいせん|くりみあせんそう|しちねんせんそう", "war"], [1914, "1914年", "サラエボ事件で皇位継承者を失った国は、{おーすとりあはんがりー|オーストリア＝ハンガリー}", "事件後の外交危機が各国の参戦へつながりました。一つの事件だけでなく、背景となる対立も重要です。", "どいつ|ろしあ|おすまんていこく", "war"], [1919, "1919年", "連合国とドイツが結んだ講和条約は、{べるさいゆ|ベルサイユ}条約", "第一次世界大戦後の国際秩序を形づくりました。国際連盟の規約も条約に含まれていました。", "ぽーつます|なんきん|ぶれすとりとふすく", "league"], [1920, "1920年", "第一次世界大戦後に発足した平和のための機関は、{こくさいれんめい|国際連盟}", "国家間の協力によって平和を守ろうとしましたが、アメリカは加盟せず、課題も抱えていました。", "こくさいれんごう|おうしゅうれんごう|きたたいせいようじょうやくきこう", "league"], [1920, "1920年", "国際連盟の本部が置かれた都市は、{じゅねーぶ|ジュネーブ}", "スイスの都市で、国際機関や国際会議が集まる拠点として発展しました。", "にゅーよーく|ぱり|うぃーん", "league"]], "world_contemporary": [[1945, "1945年", "第二次世界大戦後に発足した、{こくさいれんごう|国際連合}", "国連憲章が発効した10月24日に正式に成立しました。平和と安全の維持や国際協力を目的とします。", "こくさいれんめい|おうしゅうれんごう|とうなんあじあしょこくれんごう", "un"], [1945, "1945年", "国連憲章を作成した国際会議の開催都市は、{さんふらんしすこ|サンフランシスコ}", "50か国の代表が集まり、国連憲章を作成して署名しました。憲章の発効は同年10月です。", "にゅーよーく|じゅねーぶ|ろんどん", "un"], [1948, "1948年", "国連総会が採択した、人の権利の共通基準は、{せかいじんけんせんげん|世界人権宣言}", "国籍や人種などにかかわらず、すべての人が持つ権利を示しました。パリで採択されました。", "こくさいれんごうけんしょう|へるしんきせんげん|どくりつせんげん", "udhr"], [1949, "1949年", "北大西洋条約機構の略称は、{なとー|NATO}", "北大西洋条約機構の略称です。アメリカや西ヨーロッパの国々などが参加しました。", "あせあん|ゆねすこ|おぺっく", "nato"], [1957, "1957年", "世界初の人工衛星スプートニク1号を打ち上げた、{それん|ソ連}", "10月4日の打ち上げは宇宙開発競争を加速させ、人類の宇宙時代を象徴する出来事となりました。", "あめりか|ふらんす|ちゅうごく", "sputnik"], [1969, "1969年", "人類初の有人月面着陸を実現した、{あぽろじゅういちごう|アポロ11号}", "アメリカの宇宙計画で、7月20日に月面へ着陸しました。2人の宇宙飛行士が月面を歩きました。", "あぽろはちごう|すぷーとにくいちごう|ぼすとーくいちごう", "apollo"], [1993, "1993年", "マーストリヒト条約の発効で成立した、{おうしゅうれんごう|欧州連合}", "EUとも呼ばれます。1992年の条約署名と、1993年の発効・成立は区別して覚えましょう。", "こくさいれんめい|とうなんあじあしょこくれんごう|あふりかれんごう", "eu"], [1993, "1993年", "EUの成立につながった、{まーすとりひと|マーストリヒト}条約", "ヨーロッパ統合を進める節目となった条約で、1993年11月1日に発効しました。", "べるさいゆ|にーす|りすぼん", "eu"], [2015, "2015年", "国連で採択された持続可能な開発目標の略称は、{えすでぃーじーず|SDGs}", "貧困や環境などの課題に取り組む目標で、2030年に向けた行動を呼びかけています。", "えぬじーおー|おーでぃーえー|あいえむえふ", "sdg"], [2015, "2015年", "SDGsに定められた目標の数は、{じゅうなな|17}", "17の目標と169のターゲットからなり、経済・社会・環境の課題を関連づけて考えます。", "じゅうご|にじゅう|さんじゅう", "sdg"]]};

